  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('creative-assessment', 'Creative Assessment', 'Divergent thinking, originality, flexibility and problem reframing, with open-text responses and AI-assisted interpretation.', 'Creative Assessment measures divergent thinking, originality, flexibility, and problem-reframing ability through a mix of closed-form pattern/ideation items (deterministically scored) and open-ended written prompts (AI-interpreted only, never scored deterministically).', 'palette', v_cat, 'hybrid'::assessment_engine_type, 'medium'::assessment_difficulty, 15, 15, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'creative', 'Creative', 'Overall composite creativity score aggregating visual creativity, ideation, problem solving, flexibility, and innovation.', true, 'creative', 1)
