  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Creative Expression', 'Open-ended written prompts that surface divergent thinking and imaginative expression. These responses are AI-interpreted and do not contribute to the deterministic score.', 'Write freely — there are no right or wrong answers here.', NULL, false, 0.3, 2);
