  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('critical-thinking-depth', 'Critical Thinking Depth', 'Evaluate arguments for hidden assumptions, unstated premises, and reasoning under incomplete information.', 'Critical Thinking Depth is built around the five-skill structure of the Watson-Glaser Critical Thinking Appraisal (Watson & Glaser, 1925 onward; still one of the most widely used critical-thinking measures in professional and legal hiring): Inference, Recognition of Assumptions, Deduction, Interpretation, and Evaluation of Arguments. Each section isolates one skill so the results show exactly where your reasoning is strong versus where it slips.', 'layers', v_cat, 'standard_questionnaire'::assessment_engine_type, 'hard'::assessment_difficulty, 20, 20, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'critical-thinking', 'Critical Thinking', 'Composite score across all five Watson-Glaser skills.', true, 'logical', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'inference', 'Inference', 'Judging the truth-value of conclusions from stated facts alone.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'assumptions', 'Recognition of Assumptions', 'Spotting the specific unstated assumption a claim relies on.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'deduction', 'Deduction', 'Judging formal validity independent of real-world plausibility.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'interpretation', 'Interpretation', 'Weighing whether a conclusion is supported beyond reasonable doubt.', false, NULL, 5)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'argument-evaluation', 'Evaluation of Arguments', 'Telling strong, relevant arguments from weak or irrelevant ones.', false, NULL, 6)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Critical-thinking fundamentals are still forming — conclusions are often accepted or rejected based on plausibility rather than what the evidence actually supports.', ARRAY['Practice separating ''stated'' from ''assumed'' in everyday arguments you read', 'Work through simple syllogisms and check your answer against formal validity, not intuition', 'When reading an argument, explicitly list the unstated assumptions it depends on']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Solid on straightforward inference and deduction, but multi-step arguments or subtle unstated assumptions still catch you out.', ARRAY['Practice the ''must be true vs. might be true vs. cannot be determined'' distinction deliberately', 'Read opinion pieces and identify the strongest counter-argument before evaluating the author''s case', 'Slow down on assumption-recognition items — the obvious-sounding option is often a distractor']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Consistently separates valid inference from plausible-sounding speculation, and generally spots the argument''s real weak point.', ARRAY['Practice evaluating arguments on relevance and importance, not just whether you agree with the conclusion', 'Seek out longer, multi-premise deductive chains to sharpen precision']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Reliably distinguishes valid reasoning from rhetoric across all five skills, rarely swayed by an argument''s conclusion when judging its structure.', ARRAY['Apply this discipline to real decisions with incomplete information — write out the inference chain explicitly', 'Practice constructing counter-arguments that meet the same evaluation-of-arguments bar you hold others to']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Expert-level critical thinking — evidence, assumptions, and validity are evaluated independently of what conclusion is more comfortable or expected.', ARRAY['This is the skill set legal, analytical, and research roles are built on — consider where it''s most leveraged', 'Mentor others on the difference between a strong argument and one that merely sounds confident']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'critical-thinking', 'logical', 1);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Inference', 'Judging the degree of truth or falsity of inferences drawn from a set of facts, without assuming anything beyond what''s stated.', 'Based only on the facts given, judge whether each conclusion is true, probably true, insufficient data, probably false, or false. Pick the single best judgment.', NULL, false, 0.2, 1);
