  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('emotional-intelligence', 'Emotional Intelligence', 'Self-awareness, self-regulation, empathy, social awareness and relationship management, based on EQ-i 2.0 and MSCEIT frameworks.', 'Emotional Intelligence measures how you perceive, use, understand, and manage emotions — in yourself and others — across 9 EQ facets drawn from the EQ-i 2.0 and MSCEIT frameworks: Perceiving Emotions, Using Emotions, Understanding Emotions, Managing Emotions, Self-Perception, Self-Expression, Interpersonal Skills, Decision Making, and Stress Management.', 'heart-handshake', v_cat, 'standard_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 15, 40, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'perceiving_emotions', 'Perceiving Emotions', 'The ability to identify emotions in faces, pictures, voices, and cultural artifacts.', true, 'emotional', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'using_emotions', 'Using Emotions', 'The ability to harness emotions to facilitate various cognitive activities.', true, 'emotional', 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'understanding_emotions', 'Understanding Emotions', 'The ability to comprehend emotional language and appreciate complicated relationships among emotions.', true, 'emotional', 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'managing_emotions', 'Managing Emotions', 'The ability to regulate emotions in ourselves and in others.', true, 'emotional', 4)
