  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('executive-function-profiling', 'Executive Function Profiling', 'Planning, inhibition, working memory, and task-switching — the control processes behind goal-directed behavior.', 'Executive Function Profiling is built on the scale structure of the BRIEF (Behavior Rating Inventory of Executive Function) — the clinical standard for self- and informant-rated executive function, widely used alongside performance-based tests. It measures eight control processes: Inhibit, Shift, Emotional Control, Initiate, Working Memory, Plan/Organize, Task Monitor, and Self-Monitor.', 'layers', v_cat, 'hybrid'::assessment_engine_type, 'hard'::assessment_difficulty, 20, 24, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'executive-function', 'Executive Function', 'Composite score across all eight control processes.', true, 'logical', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'inhibit', 'Inhibit', 'Impulse control and response inhibition.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'shift', 'Shift', 'Cognitive flexibility and adapting to change.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'emotional-control', 'Emotional Control', 'Modulating emotional responses appropriately.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'initiate', 'Initiate', 'Starting tasks independently.', false, NULL, 5)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'working-memory', 'Working Memory', 'Holding and manipulating information during a task.', false, NULL, 6)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'plan-organize', 'Plan/Organize', 'Anticipating and structuring steps toward a goal.', false, NULL, 7)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'task-monitor', 'Task Monitor', 'Checking your own work as you go.', false, NULL, 8)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'self-monitor', 'Self-Monitor', 'Awareness of your impact on others.', false, NULL, 9)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Several control processes feel effortful right now — worth checking the eight scores above for which specific ones stand out most.', ARRAY['Pick the single lowest-scoring scale above and focus on one concrete habit for it (e.g. a written task list for Plan/Organize)', 'External supports (timers, checklists, written reminders) compensate well for executive function gaps — use them deliberately, not as a last resort', 'Notice patterns across your day: executive function is often more fatigue-sensitive than other cognitive measures']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'A typical mixed profile — some control processes stronger than others.', ARRAY['Look at your two lowest scales above and build one small structural habit for each', 'Notice whether your weaker scales cluster (e.g. Inhibit + Emotional Control often move together) — that pattern is informative']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable executive control across most processes, with room to grow in one or two specific scales.', ARRAY['Push your weakest scale specifically rather than practicing generically', 'Strong executive function compounds well with other cognitive strengths — check your Brain Profile for where it''s paying off most']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Consistently strong self-reported control across planning, inhibition, working memory, and task-switching.', ARRAY['This level of executive control is a genuine asset in complex, multi-step, or high-distraction work', 'Consider whether your Self-Monitor score matches how others actually perceive you — it''s worth checking that gap periodically']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Uniformly strong across all eight executive function scales.', ARRAY['This is a strong foundation for demanding, multi-threaded work — notice where it''s already paying off', 'Since this is self-report, periodically sanity-check it against how consistently your actual follow-through matches your intentions']::text[], NULL, 5);
