  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('fluid-intelligence-peak', 'Fluid Intelligence Peak', 'Novel-problem reasoning with no reliance on prior knowledge — solving patterns you''ve genuinely never seen before.', 'Fluid Intelligence Peak extends the Raven''s Progressive Matrices paradigm toward its harder, more novel end — the family of "distribution of three" rules, where a Latin-square arrangement means every row and every column contains the same three values, just never in the same order. Recognizing this rule requires checking a grid two ways at once (across the row AND down the column), which is genuinely harder to spot than a simple row/column constant, and closer to what fluid intelligence research means by reasoning that doesn''t reduce to a memorized rule.', 'brain', v_cat, 'pattern_recognition'::assessment_engine_type, 'hard'::assessment_difficulty, 25, 25, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'fluid-intelligence', 'Fluid Intelligence', 'Novel non-verbal reasoning, weighted toward distribution-of-three and multi-attribute rule types.', true, 'logical', 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'The distribution-of-three grids in particular are difficult to crack right now — recognizing a Latin-square pattern takes a different kind of scan than a simple row/column check.', ARRAY['For each grid, explicitly list what''s present in the row so far, then what''s present in the column so far — the missing cell is often forced by both at once', 'Return to Abstract Reasoning Pro to build up simpler rule-recognition first', 'Don''t assume the rule is a simple repeat — check whether all three values just appear in different order instead']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Simpler novel rules land, but the denser distribution-of-three and triple-attribute grids are still frequently missed.', ARRAY['Practice specifically on Latin-square grids until the ''check row AND column'' habit becomes automatic', 'Slow down on grids where no attribute looks constant anywhere — that''s usually the signal it''s a distribution rule']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliably solves most novel rule types, including most distribution-of-three grids.', ARRAY['Push into the triple-attribute items (shape by diagonal, color by row, rotation by column) specifically', 'This level of fluid reasoning is largely independent of vocabulary or specific knowledge — a genuine general-reasoning signal']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Consistently solves even the densest, most novel grid types quickly.', ARRAY['This is a strong, genuine fluid-intelligence signal — notice where novel-problem-solving shows up as an advantage in unfamiliar work', 'Compare this result with Abstract Reasoning Pro''s — a gap between them is informative about which rule types you find easiest']::text[], NULL, 4);
