  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('full-iq-estimation-report', 'Full IQ Estimation Report', 'A comprehensive, multi-battery composite drawing on every completed assessment to estimate a full-scale IQ range.', 'Full IQ Estimation Report doesn''t ask its own questions — it computes a composite from the Logical, Verbal, Spatial, and Memory scores in your existing Brain Profile, the same four cognitive-ability domains real full-scale IQ batteries combine (e.g. the WAIS''s Verbal Comprehension, Perceptual Reasoning, Working Memory, and Processing Speed indices). Emotional Intelligence and Creative scores are deliberately excluded from this composite, the same way Palmistry is excluded from the Brain Profile aggregate — they measure real things, just not what "IQ" traditionally refers to.', 'file-text', v_cat, 'ai_analysis'::assessment_engine_type, 'hard'::assessment_difficulty, 45, 1, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'iq-composite', 'Full-Scale Composite Estimate', 'Average of your Logical, Verbal, Spatial, and Memory Brain Profile scores — not scored from a new test.', false, NULL, 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 5, 'Not Enough Data Yet', 'You haven''t completed enough of the four core assessments (Logical Reasoning or Abstract Reasoning Pro or Fluid Intelligence Peak, Verbal Reasoning or Verbal Intelligence, Spatial Intelligence or Visuospatial Rotation, Memory Recall) for a meaningful composite. Complete at least 3 of those 4 domains, then come back.', ARRAY['Complete at least one assessment in each of the Logical, Verbal, Spatial, and Memory categories', 'The more of the ten-plus assessments in each domain you complete, the more stable this composite becomes', 'This report re-checks your data every time you take it — no need to "reset" anything']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 6, 30, 'Estimated range: below 90', 'Based on your completed assessments across the four core domains. Remember this is a self-reflection estimate, not a clinically validated IQ score — this platform has no standardization sample behind it.', ARRAY['Look at your Brain Profile page for which specific domain is pulling the composite down', 'Complete more assessments in your weaker domain(s) — this composite updates automatically as you do']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Estimated range: 90-100', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['Check your Brain Profile for your strongest and weakest of the four core domains', 'Retaking assessments you''ve improved on since your first attempt will refresh this composite']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Estimated range: 100-115', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['This composite reflects fairly balanced performance across Logical, Verbal, Spatial, and Memory', 'Consider Fluid Intelligence Peak or Verbal Reasoning Mastery if you want to stress-test your ceiling in a specific domain']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Estimated range: 115-130', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['A strong composite across all four domains — check your Brain Profile to see if one domain leads the others', 'For an actual clinical or professionally normed IQ score, a licensed psychologist administering a standardized instrument is the real route — this report doesn''t replace that']::text[], NULL, 5);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Estimated range: 130+', 'Based on your completed assessments across the four core domains — an estimate for self-reflection, not a clinically validated score.', ARRAY['An exceptional composite across Logical, Verbal, Spatial, and Memory domains', 'As with any tier here: this is a self-assessment composite, not a substitute for a professionally administered, normed IQ test']::text[], NULL, 6);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Before You Continue', 'A one-step confirmation before generating your composite.', 'This isn''t a new test — it reads your existing results.', NULL, false, 1, 1);
