    (v_ver, (select id from assessment_sections where assessment_version_id = v_ver and name = 'Before You Continue'), (select id from questions where external_key = 'fier-ack-01'), 1, 1);
  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('intelligence-profile', 'EvalOtter Intelligence Profile', 'The flagship assessment. Combines logical reasoning, numerical intelligence, memory, verbal reasoning, spatial intelligence, and pattern recognition into one EvalOtter Score.', 'The EvalOtter Intelligence Profile is the flagship assessment — a broad first read across six cognitive domains: logical reasoning, numerical intelligence, memory, verbal reasoning, spatial intelligence, and pattern recognition. It draws a curated subset of questions from the platform''s shared question library (the same items used in the dedicated single-domain assessments), so results are directly comparable to your scores on those assessments. EvalOtter assessments are designed for education, entertainment and self-discovery and are not a substitute for professional psychological, medical or clinical assessment.', 'brain', v_cat, 'hybrid'::assessment_engine_type, 'medium'::assessment_difficulty, 25, 15, true, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'logical', 'Logical', 'Pattern detection and deductive inference.', true, 'logical', 1)
