  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('language-acquisition', 'Language Acquisition', 'How readily you infer grammar and meaning from an unfamiliar constructed mini-language — a language-learning aptitude measure.', 'Language Acquisition is built on the Artificial Grammar Learning (AGL) paradigm established by Arthur Reber (1967) — one of the foundational tasks in implicit-learning research. You''re shown a set of "words" from an invented mini-language that all follow a hidden structural rule, without being told the rule. You then classify new, never-before-seen words as consistent or inconsistent with that same pattern. Performance reflects your ability to implicitly extract structure from exposure alone — a core mechanism behind natural language acquisition.', 'book-open', v_cat, 'standard_questionnaire'::assessment_engine_type, 'hard'::assessment_difficulty, 20, 20, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'implicit-learning', 'Implicit Pattern Learning', 'Ability to extract and generalize structure from exposure alone, without explicit rule instruction.', true, 'verbal', 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Classifying novel words by "feel" after brief exposure is difficult right now — this implicit pattern-extraction skill responds well to more exposure, not conscious rule-hunting.', ARRAY['Resist the urge to explicitly work out the rule — implicit learning tasks respond better to repeated exposure than analysis', 'Notice which specific letter combinations felt ''off'' in words you got wrong — that intuition is the skill building', 'This paradigm mirrors early language exposure — the same mechanism that lets children absorb grammar without being taught rules']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Some sensitivity to the underlying pattern, but longer or more novel words still get misclassified.', ARRAY['Re-read the study examples and let a ''shape'' or ''rhythm'' of the pattern form rather than counting letters', 'Trust your first instinct on borderline words — implicit learning is often more accurate than deliberate analysis']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable classification of novel words, including ones structurally different from the exact study examples.', ARRAY['This is a strong implicit-learning signal — often correlated with picking up a new language''s grammar quickly through immersion', 'Notice whether you can articulate any of the rule now, even partially — that''s the implicit knowledge surfacing']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Consistently accurate across both grammatical and ungrammatical novel words, generalizing well beyond the study set.', ARRAY['This level of implicit pattern sensitivity is a genuine asset for immersion-based language learning', 'Try noticing patterns in real language input (song lyrics, headlines) the same intuitive way, without analyzing']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Near-perfect classification of novel words — strong implicit extraction of structure from limited exposure.', ARRAY['Consider how immersion-heavy learning methods (rather than rule-first instruction) might suit you especially well for a new language', 'This kind of statistical/structural learning also shows up in music and pattern-heavy domains — worth exploring there too']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'implicit-learning', 'verbal', 0.4);
