  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('logical-reasoning', 'Logical Reasoning', 'Pattern detection, deduction, sequences and abstract reasoning — measured the way GRE and LSAT logic sections do.', 'Logical Reasoning measures how you detect patterns and draw valid conclusions from stated premises. The assessment has two parts: abstract pattern recognition (shape, color, rotation, quantity and spectrum sequences) and deductive reasoning (syllogisms and conditional logic, including recognizing when a conclusion only might be true rather than must be true).', 'git-branch', v_cat, 'standard_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 15, 15, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'logical', 'Logical Reasoning', 'Overall composite measure of logical reasoning ability, combining abstract pattern recognition and deductive inference performance.', true, 'logical', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'pattern-detection', 'Pattern Detection', 'Ability to recognize and extrapolate visual and numeric patterns.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'deduction', 'Deductive Inference', 'Ability to draw valid conclusions from premises, including recognizing invalid inferences.', false, NULL, 3)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Basic logical reasoning abilities. Pattern recognition and deductive inference are still forming, with frequent difficulty distinguishing valid conclusions from plausible-sounding but unsupported ones.', ARRAY['Practice simple pattern-completion puzzles daily to build sequence recognition', 'Study the difference between valid syllogisms and common fallacies like affirming the consequent', 'Work through logic puzzles slowly, writing out each premise before concluding']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Moderate logical reasoning abilities. You can solve straightforward pattern and deduction problems but struggle with multi-step chains or subtler invalid-inference traps.', ARRAY['Practice multi-step syllogisms involving three or more premises', 'Time yourself on pattern sequences to build speed alongside accuracy', 'Focus on distinguishing ''must be true'' from ''might be true'' conclusions']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Good logical reasoning abilities. You solve most pattern-recognition and deductive problems with consistent accuracy, occasionally missing more subtle or multi-layered items.', ARRAY['Challenge yourself with abstract reasoning puzzles that combine two changing attributes at once', 'Practice conditional logic chains (if-then-therefore) with nested conditions', 'Seek out advanced syllogism sets that include invalid-argument distractors']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Strong logical reasoning abilities. You excel at identifying patterns and drawing valid conclusions, handling most deductive traps and multi-attribute sequences correctly.', ARRAY['Tackle competition-style logic puzzles and advanced abstract reasoning sets', 'Explore formal logic notation to deepen understanding of validity vs. soundness']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Outstanding logical reasoning abilities. You demonstrate superior pattern recognition and deductive thinking skills, consistently identifying valid conclusions and complex sequence rules.', ARRAY['Pursue advanced study in formal logic, discrete mathematics, or algorithmic problem solving', 'Apply your reasoning strengths to real-world analytical or strategic decision-making roles']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'logical', 'logical', 1);
