  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('memory-palace-challenge', 'Memory Palace Challenge', 'A method-of-loci memory exercise — place items along an imagined route, then recall them in order.', 'Memory Palace Challenge is built on the Method of Loci ("memory palace") — the oldest documented memory technique, traced to ancient Greek and Roman rhetoric, and still the core technique behind competitive memory-sport disciplines like the World Memory Championships'' serial-recall events. You study a route of locations, each holding one item, then recall the items in the exact order they appeared along the route. Recall is scored by strict serial position — an item remembered but placed in the wrong slot doesn''t count, matching how serial recall is scored in memory research.', 'map', v_cat, 'memory_exercise'::assessment_engine_type, 'hard'::assessment_difficulty, 15, 12, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'loci-memory', 'Memory Palace Recall', 'Composite score across ordered recall and position-probe accuracy.', true, 'memory', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'sequence-recall', 'Ordered Recall', 'Recalling the full route''s items in exact serial order.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'position-accuracy', 'Position Accuracy', 'Correctly identifying what was at a specific stop.', false, NULL, 3)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Ordered recall across a full route is difficult right now — the technique itself takes practice before the palace "sticks."', ARRAY['Start with shorter routes (3-4 stops) and build up gradually', 'Make the mental images vivid and slightly absurd — bizarre images are easier to recall than plain ones', 'Walk the route in your head at least twice before attempting recall']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Shorter routes are manageable, but longer ones or a route studied only once lose items partway through.', ARRAY['Practice the same route repeatedly until the order feels automatic before moving to a new one', 'Use real, familiar locations (your actual home) instead of generic ones — familiarity anchors the route']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable ordered recall across most routes, with occasional slips on the longer ones.', ARRAY['Push route length further — competitive memory athletes use routes with dozens of stops', 'Practice recalling routes out of order (e.g. "what was at stop 5?") to strengthen the underlying spatial map, not just the sequence']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Consistently accurate ordered recall even on the longest route, with strong position accuracy too.', ARRAY['This technique scales well — try applying it to real material you need to memorize (a speech, a list, key facts)', 'Build multiple palaces for different topics so they don''t interfere with each other']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Near-perfect ordered recall across every route — the core skill behind competitive memory-sport performance.', ARRAY['This is genuinely competition-level serial recall — the World Memory Championships'' disciplines use the same core technique at larger scale', 'Consider extending routes further, or memorizing genuinely long real-world sequences']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'loci-memory', 'memory', 1);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Route 1: Home', 'A 5-stop route through a house.', 'Study this route, in order: 1. Front Door → Umbrella · 2. Hallway → Painting · 3. Kitchen → Teapot · 4. Living Room → Lamp · 5. Bedroom → Alarm Clock. Picture yourself walking the route, seeing each item at its stop.', NULL, false, 0.2, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Route 2: Cottage Garden', 'A 6-stop route through a garden and cottage.', 'Study this route, in order: 1. Garden Gate → Watering Can · 2. Porch → Welcome Mat · 3. Foyer → Mirror · 4. Staircase → Candle · 5. Study → Globe · 6. Attic → Trunk.', NULL, false, 0.25, 2);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Route 3: Office Building', 'A 7-stop route through an office building.', 'Study this route, in order: 1. Lobby → Fountain · 2. Elevator → Plant · 3. Office Floor → Whiteboard · 4. Break Room → Coffee Pot · 5. Conference Room → Projector · 6. Supply Closet → Stapler · 7. Rooftop → Antenna.', NULL, false, 0.25, 3);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Route 4: Mountain Trail', 'An 8-stop route along a hiking trail.', 'Study this route, in order: 1. Trailhead → Compass · 2. Bridge → Rope · 3. Meadow → Canteen · 4. Forest Edge → Lantern · 5. Cave Mouth → Torch · 6. River Bend → Fishing Rod · 7. Campsite → Tent · 8. Summit → Flag.', NULL, false, 0.3, 4);
