  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'ISLT Shopping List', 'International Shopping List Test — participants study a 12-item shopping list, then attempt to recognize the items from a mixed grid of targets and distractors.', 'You will see 12 shopping list items for 30 seconds. Study them carefully. Afterward, select the items you remember from a grid of 20 items (12 targets + 8 distractors).', 30, false, 0.2, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'ADAS-Cog Word Recall', 'Alzheimer''s Disease Assessment Scale-Cognitive word list test — 10 words are shown sequentially, then freely recalled by typing.', '10 words will be displayed one at a time, 3 seconds each. After all words have been shown, type as many as you can remember, in any order.', 30, false, 0.2, 2);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Logical Memory Test', 'Wechsler-style Logical Memory subtest — a short news-style story is read, then comprehension/recall questions are answered about its details.', 'Read the story ''The Brave Firefighter'' carefully. You have 45 seconds. Afterward, answer 5 multiple-choice questions about details from the story.', 45, false, 0.2, 3);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'SKT Speed Test', 'Syndrom-Kurztest-inspired speed naming and object recognition task — 8 objects are named as quickly as possible, then recognized from a mixed grid.', 'You will be shown 8 objects one at a time. Select the correct name for each as quickly as possible. Afterward, identify which objects you saw from a mixed grid of 14 (8 targets + 6 distractors).', NULL, false, 0.2, 4);
