  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('metrics', 'Metrics / Numerical Intelligence', 'Numerical reasoning, percentages, ratios, sequences and data interpretation under light time pressure.', 'Metrics measures numerical reasoning across five areas: mental arithmetic, percentages, ratios and proportions, number sequences, and data interpretation from tables and charts — the kind of quantitative reasoning used in everyday financial and analytical decisions.', 'calculator', v_cat, 'timed_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 15, 20, false, 'free'::assessment_access, 'published'::assessment_status)
