  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Numerical reasoning under time pressure is still forming. Percentage and ratio calculations took noticeably longer, and multi-step data interpretation questions were the hardest to complete accurately.', ARRAY['Practice mental percentage calculations daily (10%, 25%, then combine for others).', 'Drill ratio and proportion word problems until the setup becomes automatic.', 'Work through simple bar/table data questions slowly before adding a timer.']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'You handle straightforward calculations reliably but slow down or make errors on multi-step percentage, ratio, or data-interpretation problems.', ARRAY['Practice two-step percentage problems (e.g. percentage of a percentage).', 'Time yourself on sequence puzzles to build pattern-spotting speed.', 'Practice reading two-variable tables and cross-referencing rows and columns.']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'You solve most numerical reasoning problems accurately and at a reasonable pace, with occasional slips on compound percentage or ratio questions.', ARRAY['Practice compound percentage change (successive increases/decreases).', 'Work through GMAT/GRE-style data sufficiency and interpretation sets.', 'Push your sequence-solving speed with mixed arithmetic/geometric patterns.']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'You process numerical information quickly and accurately across arithmetic, percentages, ratios, and data interpretation, with only the hardest compound-rule sequences slowing you down.', ARRAY['Practice advanced data-interpretation sets with multiple linked tables.', 'Time yourself against progressively shorter limits to sharpen speed further.', 'Apply this strength to real financial or analytical decision-making.']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Your numerical reasoning is exceptional — fast, accurate, and reliable across every category tested, including compound percentage changes, multi-step ratios, and dense tabular data.', ARRAY['Pursue quantitative fields (finance, data science, engineering, actuarial work) that leverage this strength.', 'Take on advanced numerical reasoning batteries (GMAT Quant, actuarial exams) to keep finding ceiling.', 'Mentor others in mental-math and estimation techniques.']::text[], NULL, 5);
