  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('numerical-agility', 'Numerical Agility', 'Rapid-fire mental math and estimation under a tight clock — built for speed as much as accuracy.', 'Numerical Agility is built around the numerical-reasoning item types published for the Wonderlic Personnel Test (now Wonderlic Cognitive Ability Test) — one of the most widely used short-form cognitive ability tests, run under a strict time limit specifically to measure how much correct reasoning you can produce per minute, not just whether you can eventually get there. This assessment isolates the numerical portion (arithmetic, percentages/ratios, number series, word problems) under the same kind of time pressure.', 'zap', v_cat, 'timed_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 10, 24, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'numerical-agility', 'Numerical Agility', 'Composite score across arithmetic, ratios, number series, and word problems, all under a single overall time limit.', true, 'logical', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'arithmetic', 'Arithmetic & Percentages', 'Speed and accuracy on direct computation.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'ratios', 'Ratios & Proportions', 'Correctly scaling quantities and rates.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'number-series', 'Number Series', 'Identifying numeric patterns and extrapolating them.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'word-problems', 'Word Problems', 'Translating scenarios into correct calculations.', false, NULL, 5)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Under time pressure, numerical problem-solving slows down considerably — the reasoning is there, but not yet fast enough to finish under a tight clock.', ARRAY['Practice mental math (percentages, simple ratios) without a calculator, daily, for a few minutes', 'Work on recognizing common word-problem structures (rate, ratio, percent-change) so setup is faster', 'Time yourself on easy problems first to build speed before tackling harder ones']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Solid accuracy on problems you have time for, but the clock is clearly a limiting factor — some items are likely left unanswered or rushed.', ARRAY['Practice number series specifically — pattern recognition speeds up a lot with exposure', 'Build a mental toolkit of shortcuts for percentages (10% then adjust, rather than long division)']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Good speed-accuracy balance — most problem types are handled comfortably within the time limit, with occasional slowdowns on multi-step word problems.', ARRAY['Push on the hardest word-problem types (multi-step, rate-and-distance) to close remaining gaps', 'Practice number series with less obvious rules (alternating operations, not just +/- constant)']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Fast and accurate across arithmetic, ratios, series, and word problems — the kind of numerical fluency that shows up as an advantage under any deadline.', ARRAY['This speed-accuracy combination transfers directly to data-heavy or finance-adjacent work', 'Try timed practice sets with a shorter clock to push the ceiling further']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Elite numerical agility — correct, fast, and consistent across every problem type under real time pressure.', ARRAY['Consider roles that reward rapid quantitative judgment — trading, analytics, engineering estimation', 'Mentor others on mental-math shortcuts that build this kind of speed']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'numerical-agility', 'logical', 0.5);
