  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Arithmetic & Percentages', 'Direct computation under time pressure — no calculator, mental math only.', 'Solve each problem as quickly and accurately as you can. There''s one clock for the whole assessment, not per question — move on if you get stuck.', NULL, false, 0.25, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Ratios & Proportions', 'Scaling quantities and rates correctly under time pressure.', 'Solve each ratio or proportion problem.', NULL, false, 0.25, 2);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Number Series', 'Identifying the rule governing a sequence of numbers and extrapolating it.', 'Find the pattern and choose what comes next.', NULL, false, 0.25, 3);
