  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('phonological-awareness', 'Phonological Awareness', 'Rhyme, syllable, and sound-manipulation tasks measuring how you perceive and work with the sounds of language.', 'Phonological Awareness is built around the subtest structure of the CTOPP-2 (Comprehensive Test of Phonological Processing, Second Edition — the standard clinical/educational measure of phonological processing): Elision (removing a sound from a spoken word to form another word), Blending Words (synthesizing separate sounds into a word), and Sound Matching (identifying shared initial or final sounds). The CTOPP-2 is administered orally; since this platform has no audio-recording input, every item is adapted to a text/reading format — see the source note below.', 'volume-2', v_cat, 'standard_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 12, 24, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'phonological-awareness', 'Phonological Awareness', 'Composite score across elision, blending, and sound matching.', true, 'verbal', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'elision', 'Elision', 'Ability to remove a phonological segment from a word.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'blending', 'Blending', 'Ability to synthesize separate sounds into a word.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'sound-matching', 'Sound Matching', 'Ability to identify shared initial/final sounds across words.', false, NULL, 4)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Sound-manipulation skills are still forming — breaking words into their component sounds and recombining them takes deliberate effort.', ARRAY['Practice saying words slowly, sound by sound, before trying to remove or blend a sound', 'Start with elision on simple one-syllable words before moving to blends and clusters', 'Read aloud regularly — hearing your own pronunciation reinforces the sound-to-letter mapping']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Comfortable with simple sound manipulation, but multi-sound blends and less common sound-matching pairs slow you down.', ARRAY['Practice blending 3-4 separate sounds into words without seeing them written first', 'Work on sound matching across less obvious pairs (matching endings, not just starts)']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable phonemic manipulation across elision, blending, and matching, with occasional slips on trickier consonant clusters.', ARRAY['Challenge yourself with elision on words with consonant blends (e.g. removing one sound from a three-consonant cluster)', 'Practice with multisyllabic words rather than just single syllables']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Fast, accurate sound manipulation across all three skills — this level of phonological awareness underlies strong reading and spelling ability.', ARRAY['This skill transfers directly to learning new languages and to spelling irregular words', 'Try phonological awareness with unfamiliar or invented words to test the skill in isolation from memorized vocabulary']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Expert-level phonological processing — sounds are manipulated automatically and accurately across every task type.', ARRAY['Consider how this strength could support tutoring, speech-language work, or language learning', 'This is a strong predictor of ease learning additional languages — a good time to try one']::text[], NULL, 5);
