  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Elision', 'Removing a sound from a spoken word to form a different, real word.', 'Each item names a word and a sound to remove. Choose what''s left after removing it.', NULL, false, 0.34, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Blending Words', 'Synthesizing individual sounds into a whole word.', 'Each item gives you separate sounds. Choose the word they form when blended together.', NULL, false, 0.33, 2);
