  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('social-cognition-assessment', 'Social Cognition Assessment', 'Reading intentions, perspective-taking, and interpreting social scenarios — the cognitive side of understanding people.', 'Social Cognition is built around the paradigm of Happé''s Strange Stories Task (Happé, 1994), the most widely cited theory-of-mind test beyond childhood — short vignettes end in a character saying something that isn''t literally true (a lie, a joke, sarcasm, a white lie, pretense), and understanding why requires reasoning about what the character believes, wants, or intends. The original task is administered verbally with open-ended responses hand-coded by a researcher; here every vignette is answered as a forced choice between the correct mental-state explanation and plausible-but-wrong alternatives, so it can be scored deterministically.', 'users', v_cat, 'standard_questionnaire'::assessment_engine_type, 'medium'::assessment_difficulty, 15, 20, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'social-cognition', 'Social Cognition', 'Composite score across non-literal language and social reasoning.', true, 'emotional', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'non-literal-language', 'Non-Literal Language', 'Correctly interpreting lies, jokes, irony, and figurative speech.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'social-reasoning', 'Social Reasoning', 'Tracking beliefs, intentions, and misunderstandings distinct from objective reality.', false, NULL, 3)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Social scenarios are often read at face value — the literal words rather than what the speaker actually believed, wanted, or intended.', ARRAY['When someone says something surprising, pause and ask what they might believe that would make it make sense', 'Practice noticing the difference between what''s said and what''s meant in conversations you observe', 'Watch for social cues like tone and context that signal irony, jokes, or tact']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Straightforward social cues like obvious jokes or lies are read correctly, but subtler cases — white lies, persuasion, double meanings — are harder to untangle.', ARRAY['Practice distinguishing white lies (said to protect feelings) from ordinary lies (said for self-interest)', 'Pay attention to a speaker''s likely goal, not just their literal words, when interpreting persuasion']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliably infers what other people believe and intend, correctly separating that from objective reality in most scenarios.', ARRAY['Practice with layered scenarios where a character''s belief is itself mistaken', 'Apply this skill deliberately in real conversations — check your read against what actually happened']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Consistently accurate at reading intentions, irony, and non-literal language, rarely taking a figurative statement at face value.', ARRAY['This is a strong foundation for roles involving negotiation, mediation, or coaching', 'Notice how this skill helps you catch misunderstandings before they escalate']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Expert-level social cognition — mental states, intentions, and non-literal meaning are read quickly and accurately across every scenario type.', ARRAY['Consider where this strength is most valuable — teaching, therapy, leadership, and mediation all lean on it heavily', 'Mentor others on distinguishing what''s said from what''s meant']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'social-cognition', 'emotional', 0.5);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Non-Literal Language', 'Understanding lies, white lies, jokes, irony, and figures of speech — statements that aren''t literally true but make sense once you understand why they were said.', 'Read each short scenario, then choose the explanation that best captures why the character said what they said.', NULL, false, 0.5, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Social Reasoning', 'Understanding misunderstandings, persuasion, and pretense — situations that require tracking what someone else believes or intends, separate from what''s actually true.', 'Read each short scenario, then choose the explanation that best accounts for the character''s behavior.', NULL, false, 0.5, 2);
  insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values (v_ver, 'social-cognition', 'average'::scoring_formula, NULL, NULL, NULL);
  insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values (v_ver, 'non-literal-language', 'sum'::scoring_formula, NULL, '{"min":0,"max":10}'::jsonb, NULL);
