  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('speed-processing-index', 'Speed Processing Index', 'Simple, low-difficulty tasks answered as fast as possible — an index of raw cognitive processing speed.', 'Speed Processing Index is built on the simple/choice reaction-time paradigm established by Arthur Jensen''s chronometric research — one of the foundational bodies of work linking raw processing speed to general cognitive ability. Every task here is deliberately trivial in difficulty (string matching, basic arithmetic, number comparison, category judgment) so that response time, not problem difficulty, is what''s actually being measured.', 'timer', v_cat, 'timed_questionnaire'::assessment_engine_type, 'easy'::assessment_difficulty, 8, 40, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'processing-speed', 'Processing Speed', 'Speed and accuracy on simple, low-difficulty judgments.', true, 'logical', 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Even on these deliberately simple judgments, speed or accuracy is lagging — worth another attempt when less fatigued, since this measure is sensitive to mental fatigue.', ARRAY['Retake when well-rested — processing speed is one of the most fatigue-sensitive cognitive measures', 'Focus purely on the decision itself, not double-checking — these tasks are designed to not need double-checking', 'Notice which section felt slowest — that''s more informative than the overall number']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Solid accuracy with moderate speed — typical for tasks this simple under real time pressure.', ARRAY['Practice trusting your first instinct on simple judgments like these — hesitation costs more than it helps here', 'Notice whether accuracy or speed is the bigger factor in your score']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Fast, accurate responses across all four judgment types, with minor slowdowns on the trickier comparisons.', ARRAY['This level of raw processing speed is a genuine asset in any task requiring rapid simple decisions', 'Try the assessment again later in the day to see how speed varies with mental state']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Consistently fast and accurate across every section — near-ceiling performance on tasks this simple.', ARRAY['Raw processing speed at this level often correlates with strong performance on more complex timed cognitive tasks too', 'Consider how this speed shows up in real-world quick-decision contexts']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Near-instant, accurate responses across all four judgment types — elite raw processing speed.', ARRAY['This is a genuinely fast baseline processing speed — a real asset across nearly any time-pressured cognitive task', 'Worth noting alongside your other timed assessment results, since processing speed tends to be a general factor']::text[], NULL, 5);
