  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('verbal-reasoning-mastery', 'Verbal Reasoning Mastery', 'An advanced-tier follow-on to Verbal Reasoning, pushing into denser passages and multi-step argument chains.', 'Verbal Reasoning Mastery is built around the three question types that make up the GRE General Test''s Verbal Reasoning measure — one of the most widely used graduate-admissions verbal assessments: Text Completion (fill a blank using context and vocabulary), Sentence Equivalence (pick two answers that complete a sentence equivalently), and Reading Comprehension (short passages with inference questions).', 'message-square', v_cat, 'timed_questionnaire'::assessment_engine_type, 'hard'::assessment_difficulty, 25, 30, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'verbal', 'Verbal Reasoning', 'Composite score across text completion, sentence equivalence, and reading comprehension.', true, 'verbal', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'text-completion', 'Text Completion', 'Using context and vocabulary to complete a sentence''s meaning.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'sentence-equivalence', 'Sentence Equivalence', 'Recognizing which of several words are semantically equivalent in context.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'reading-comprehension', 'Reading Comprehension', 'Drawing correct inferences from a short passage.', false, NULL, 4)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Advanced verbal reasoning is still forming — dense vocabulary-in-context and multi-clause passages take significant effort to parse under time pressure.', ARRAY['Read one long-form article daily and summarize its main claim in one sentence', 'Build vocabulary through context (guess the meaning, then check) rather than flashcard memorization alone', 'Practice text completion untimed first, then reintroduce the clock']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Comfortable with straightforward vocabulary-in-context, but sentence equivalence''s double-correct-answer format and denser passages slow you down.', ARRAY['Practice eliminating obviously-wrong pairs first in sentence equivalence before comparing the remainder', 'Read passages once for structure, then again for the specific inference being asked']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliable across all three formats, occasionally slowed by unfamiliar vocabulary or a passage''s more subtle inference.', ARRAY['Push into denser nonfiction (academic abstracts, opinion essays with counter-arguments) to raise your inference ceiling', 'Time yourself on full timed sets to build stamina, not just accuracy']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Fast and precise across text completion, sentence equivalence, and reading comprehension, rarely tripped up by a distractor that merely sounds plausible.', ARRAY['This level of verbal reasoning transfers directly to graduate-level reading and argument-heavy writing', 'Try passages from unfamiliar academic fields to stress-test comprehension without domain familiarity to lean on']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Expert-level verbal reasoning — vocabulary, equivalence judgments, and passage inference are all handled quickly and precisely under time pressure.', ARRAY['Consider fields that lean heavily on precise written argument — law, editing, research, policy analysis', 'Mentor others on distinguishing a genuinely equivalent word choice from one that merely fits the sentence']::text[], NULL, 5);
