  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('verbal-reasoning', 'Verbal Reasoning', 'Comprehension, analogies, inference and argument evaluation — GRE Verbal / LSAT Logical Reasoning calibre.', 'Verbal Reasoning measures cognitive efficiency in language: how fast and accurately you process arguments, extract logical conclusions, and select the exact word a context demands. It covers four areas — Deductive Reasoning, Critical Reasoning, Reading Comprehension, and Verbal Precision.', 'message-square', v_cat, 'timed_questionnaire'::assessment_engine_type, 'hard'::assessment_difficulty, 18, 24, false, 'free'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'verbal', 'Verbal Reasoning', 'Composite measure of speed and accuracy in deductive logic, argument evaluation, reading comprehension, and word precision.', true, 'verbal', 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'deductive', 'Deductive Reasoning', 'Ability to derive conclusions that must be true from stated premises.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'critical', 'Critical Reasoning', 'Ability to identify assumptions, flaws, strengtheners, and weakeners in arguments.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'reading', 'Reading Comprehension', 'Ability to extract purpose, tone, and supported inference from passages.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'precision', 'Verbal Precision', 'Ability to select the exact word or relationship a context demands.', false, NULL, 5)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Your results indicate an opportunity to build core deductive and critical-reasoning technique before timed practice will compound — accuracy improvements will move this score faster than speed drills at this stage.', ARRAY['Practice basic syllogisms and modus tollens/modus ponens patterns daily.', 'Slow down on critical reasoning stimuli to fully map the argument before answering.', 'Build vocabulary through active reading rather than word lists alone.']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'You show solid instincts on individual items but inconsistent performance across question types — targeted practice on your weaker category will move this score fastest.', ARRAY['Identify your weakest of the four categories and drill it specifically.', 'Time yourself on practice sets to build comfort under pressure.', 'Practice distinguishing ''must be true'' conclusions from merely plausible ones.']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'You reliably reach correct conclusions but have room to sharpen either raw processing speed or precision under time pressure — closing that gap is where the largest score gains typically live.', ARRAY['Focus on reducing time-per-question without sacrificing accuracy.', 'Practice eliminating distractor answers quickly in critical reasoning.', 'Sharpen precision with nuanced synonym and analogy drills.']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'You extract logical conclusions and evaluate arguments with strong speed and precision, on par with high-performing graduate program applicants.', ARRAY['Maintain sharpness with periodic timed practice sets.', 'Push into harder, denser reading passages to extend your ceiling.', 'Practice under increasingly compressed time limits.']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'You process language and argument structure at a level consistent with top-decile performance on graduate and executive verbal assessments — fast, accurate, and rarely misled by distractor logic.', ARRAY['Maintain performance with occasional high-difficulty practice.', 'Consider mentoring or teaching reasoning technique to reinforce mastery.', 'Explore adjacent skill areas such as quantitative or abstract reasoning.']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'verbal', 'verbal', 1);
  insert into assessment_versions (assessment_id, version_number, status, settings, published_at) values (v_ass, v_num, 'published'::assessment_status, '{"allowBackNavigation":true,"randomizeSections":false,"randomizeQuestions":false,"randomizeAnswerOrder":false,"showProgressBar":true,"showInstructionsBetweenSections":true,"autosaveIntervalSeconds":10,"totalTimeLimitSeconds":null}'::jsonb, now()) returning id into v_ver;
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Deductive Reasoning', 'Apply top-down logic to premises and identify the conclusion that must be true.', 'Read each set of premises and select the conclusion that must be true.', NULL, false, 1, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Critical Reasoning', 'Evaluate arguments for assumptions, flaws, and the evidence that strengthens or weakens them.', 'Read each stimulus and answer the question about the argument''s structure, assumptions, or evidence.', NULL, false, 1, 2);
