  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('visuospatial-rotation', 'Visuospatial Rotation', 'Mental rotation of 3D objects — identify which option is the same shape rotated, not a mirrored fake.', 'Visuospatial Rotation is built on the Mental Rotation Test paradigm (Vandenberg & Kuse, 1978; originating from Shepard & Metzler, 1971) — the classic measure of the ability to mentally rotate a shape and recognize it from a different orientation. You''re shown a target shape and must pick which option is a genuine rotation of it, rejecting mirrored (chirality-flipped) look-alikes — the core challenge the paradigm is built around.', 'rotate-cw', v_cat, 'pattern_recognition'::assessment_engine_type, 'hard'::assessment_difficulty, 15, 18, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'mental-rotation', 'Mental Rotation', 'Ability to mentally rotate a shape and distinguish a true rotation from a mirrored look-alike.', true, 'spatial', 1)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Developing', 'Distinguishing a true rotation from a mirrored look-alike is difficult right now — a very common starting point, since mirror-image confusion is exactly what this paradigm is designed to probe.', ARRAY['Trace one distinctive feature (a notch or corner) on the target and track where it ends up after rotating in your head, rather than judging the whole shape''s silhouette at once', 'Practice with physical objects (rotate a real asymmetric object like a shoe or a hand) to build the underlying spatial-transformation skill', 'Slow down specifically on options that look ''almost right'' — those are usually the mirrored distractors']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Average', 'Catches obvious mismatches but the closely-matched mirrored distractors still cause errors.', ARRAY['Practice specifically on mirror-vs-rotation discrimination — cover the target and try to redraw it rotated before looking at the options', 'Pick one asymmetric feature as your anchor and check it first on every option before considering the rest']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Strong', 'Reliably identifies true rotations and rejects mirrored distractors on most trials.', ARRAY['Push your speed on easier trials — accuracy is already solid there', 'Notice whether larger rotation angles (further from the target''s original orientation) slow you down more — that''s a normal, well-documented pattern']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Very Strong', 'Fast, accurate rotation-vs-mirror discrimination across nearly every trial, including the harder rotation angles.', ARRAY['This is a strong, genuine spatial-reasoning advantage — fields like engineering, design, and surgery lean on exactly this skill', 'Compare this result with Spatial Intelligence''s matrix-reasoning score — they draw on related but distinct spatial skills']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Exceptional', 'Near-perfect mental rotation performance across every trial and angle tested.', ARRAY['This is an elite spatial-rotation result — notice where it shows up as a real advantage in 3D-reasoning-heavy work', 'Consider fields that specifically reward strong 3D spatial reasoning under time pressure']::text[], NULL, 5);
  insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values (v_ass, 'mental-rotation', 'spatial', 0.5);
